INSERT INTO `repository`
VALUES (10000011, 'majava1314/dkd-parent', 'https://gitee.com/majava1314/dkd-parent.git',
        '<p align=\"center\" >\n<span style=\"background-color: #5373e0;display: inline-block\"> \n<img alt=\"logo\" src=\"https://likede2-admin.itheima.net/img/logo.3673fab5.png\">\n</span>\n</p>\n<h1 align=\"center\" style=\"margin: 30px 0 30px; font-weight: bold;\">帝可得</h1>\n<h4 align=\"center\">基于RuoYi（SpringBoot+Vue前后端分离）的Java快速开发框架</h4>\n\n\n## 背景介绍\n\n智能售货机项目是随着互联网及物联网技术的普及及发展，运用现有技术对传统售货机进行改造升级，从B端角度来提升传统售货机的的运营、运维效率，通过运营数据的采集和分析不断优化运营方案，降低运营、运维成本，缩短B端用户的盈利周期，针对不同的摆放点位及商业场景，匹配的不同机型及不同的商品供B端用户贴合自身特点来快速实现商业价值；针对C端用户的购物体验，将传统的纸币硬币购物流程替换成支付宝、微信、银联等线上扫码支付(或刷脸支付)等快捷支付方式。\n\n业务模式分为，自营模式、加盟模式或点位主分成模式等。\n\n## 业务介绍\n随着售货机平台方运营售货机设备数量及点位数量越来越多，为了降低成本加快运营和运维效率将有限的资源迅速变现，平台方将系统做了切分，其中客户端包含三个：面向维修人员的运维客户端，主要用来跟踪和解决维修人员的日常工作和及时处理设备故障；运营客户端，主要用来提高日常运营效率，减少缺货设备，提高设备的盈利能力；C端用户客户端，面向C端用户的客户端，提高用户体验，缩短用户购物流程。\n\n为了更好的针对不同B端用户的使用习惯，平台端切分为两个端：平台管理端，主要为了管理设备、货道、商品、工单及运营、运维数据。合作商后台：针对有大量点位但是没有运营能力的用户提供数据接入和销售分成的管理。\n',
        40704041);
INSERT INTO `repository`
VALUES (10000012, 'majava1314/dkd-vue', 'https://gitee.com/majava1314/dkd-vue.git',
        '<p align=\"center\" >\n<span style=\"background-color: #5373e0;display: inline-block\"> \n<img alt=\"logo\" src=\"https://likede2-admin.itheima.net/img/logo.3673fab5.png\">\n</span>\n</p>\n<h1 align=\"center\" style=\"margin: 30px 0 30px; font-weight: bold;\">帝可得</h1>\n<h4 align=\"center\">基于RuoYi（SpringBoot+Vue前后端分离）的Java快速开发框架</h4>\n\n\n## 背景介绍\n\n智能售货机项目是随着互联网及物联网技术的普及及发展，运用现有技术对传统售货机进行改造升级，从B端角度来提升传统售货机的的运营、运维效率，通过运营数据的采集和分析不断优化运营方案，降低运营、运维成本，缩短B端用户的盈利周期，针对不同的摆放点位及商业场景，匹配的不同机型及不同的商品供B端用户贴合自身特点来快速实现商业价值；针对C端用户的购物体验，将传统的纸币硬币购物流程替换成支付宝、微信、银联等线上扫码支付(或刷脸支付)等快捷支付方式。\n\n业务模式分为，自营模式、加盟模式或点位主分成模式等。\n\n## 业务介绍\n随着售货机平台方运营售货机设备数量及点位数量越来越多，为了降低成本加快运营和运维效率将有限的资源迅速变现，平台方将系统做了切分，其中客户端包含三个：面向维修人员的运维客户端，主要用来跟踪和解决维修人员的日常工作和及时处理设备故障；运营客户端，主要用来提高日常运营效率，减少缺货设备，提高设备的盈利能力；C端用户客户端，面向C端用户的客户端，提高用户体验，缩短用户购物流程。\n\n为了更好的针对不同B端用户的使用习惯，平台端切分为两个端：平台管理端，主要为了管理设备、货道、商品、工单及运营、运维数据。合作商后台：针对有大量点位但是没有运营能力的用户提供数据接入和销售分成的管理。\n',
        40704129);
INSERT INTO `repository`
VALUES (10000013, 'majava1314/edu-admin', 'https://gitee.com/majava1314/edu-admin.git',
        '# vue-admin-template\n\n> 这是一个 极简的 vue admin 管理后台 它只包含了 Element UI & axios & iconfont & permission control & lint，这些搭建后台必要的东西。\n\n[线上地址](http://panjiachen.github.io/vue-admin-template)\n\n[国内访问](https://panjiachen.gitee.io/vue-admin-template)\n\n## Extra\n\n如果你想要根据用户角色来动态生成侧边栏和 router，你可以使用改分支[permission-control](https://github.com/PanJiaChen/vue-admin-template/tree/permission-control)\n\n本项目基于`webpack4`开发，若还想使用`webpack3`开发，请使用该分支[webpack3](https://github.com/PanJiaChen/vue-admin-template/tree/webpack3)\n\n如果你想使用基于 vue + typescript 的管理后台, 可以看看这个项目: [vue-typescript-admin-template](https://github.com/Armour/vue-typescript-admin-template) (鸣谢: [@Armour](https://github.com/Armour))\n\n## 相关项目\n\n[vue-element-admin](https://github.com/PanJiaChen/vue-element-admin)\n\n[electron-vue-admin](https://github.com/PanJiaChen/electron-vue-admin)\n\n[vue-typescript-admin-template](https://github.com/Armour/vue-typescript-admin-template)\n\n写了一个系列的教程配套文章，如何从零构建后一个完整的后台项目:\n\n- [手摸手，带你用 vue 撸后台 系列一(基础篇)](https://juejin.im/post/59097cd7a22b9d0065fb61d2)\n- [手摸手，带你用 vue 撸后台 系列二(登录权限篇)](https://juejin.im/post/591aa14f570c35006961acac)\n- [手摸手，带你用 vue 撸后台 系列三 (实战篇)](https://juejin.im/post/593121aa0ce4630057f70d35)\n- [手摸手，带你用 vue 撸后台 系列四(vueAdmin 一个极简的后台基础模板,专门针对本项目的文章,算作是一篇文档)](https://juejin.im/post/595b4d776fb9a06bbe7dba56)\n- [手摸手，带你封装一个 vue component](https://segmentfault.com/a/1190000009090836)\n\n## Build Setup\n\n```bash\n# Clone project\ngit clone https://github.com/PanJiaChen/vue-admin-template.git\n\n# Install dependencies\nnpm install\n\n# 建议不要用cnpm  安装有各种诡异的bug 可以通过如下操作解决npm速度慢的问题\nnpm install --registry=https://registry.npm.taobao.org\n\n# Serve with hot reload at localhost:9528\nnpm run dev\n\n# Build for production with minification\nnpm run build\n\n# Build for production and view the bundle analyzer report\nnpm run build --report\n```\n\n## Demo\n\n![demo](https://github.com/PanJiaChen/PanJiaChen.github.io/blob/master/images/demo.gif)\n\n### Element-Ui 使用 cdn 教程\n\n首先找到 `index.html` ([根目录下](https://github.com/PanJiaChen/vue-admin-template/blob/element-ui-cdn/index.html))\n\n引入 Element 的 css 和 js ，并且引入 vue 。因为 Element-Ui 是依赖 vue 的，所以必须在它之前引入 vue 。\n\n之后找到 [webpack.base.conf.js](https://github.com/PanJiaChen/vue-admin-template/blob/element-ui-cdn/build/webpack.base.conf.js) 加入 `externals` 让 webpack 不打包 vue 和 element\n\n```\nexternals: {\n  vue: \'Vue\',\n  \'element-ui\':\'ELEMENT\'\n}\n```\n\n之后还有一个小细节是如果你用了全局对象方式引入 vue，就不需要 手动 `Vue.use(Vuex）` ，它会自动挂载，具体见 [issue](https://github.com/vuejs/vuex/issues/731)\n\n最终你可以使用 `npm run build --report` 查看效果\n如图：\n![demo](https://panjiachen.github.io/images/element-cdn.png)\n\n**[具体代码](https://github.com/PanJiaChen/vue-admin-template/commit/746aff560932704ae821f82f10b8b2a9681d5177)**\n\n**[对应分支](https://github.com/PanJiaChen/vue-admin-template/tree/element-ui-cdn)**\n\n## Browsers support\n\nModern browsers and Internet Explorer 10+.\n\n| [<img src=\"https://raw.githubusercontent.com/alrra/browser-logos/master/src/edge/edge_48x48.png\" alt=\"IE / Edge\" width=\"24px\" height=\"24px\" />](http://godban.github.io/browsers-support-badges/)</br>IE / Edge | [<img src=\"https://raw.githubusercontent.com/alrra/browser-logos/master/src/firefox/firefox_48x48.png\" alt=\"Firefox\" width=\"24px\" height=\"24px\" />](http://godban.github.io/browsers-support-badges/)</br>Firefox | [<img src=\"https://raw.githubusercontent.com/alrra/browser-logos/master/src/chrome/chrome_48x48.png\" alt=\"Chrome\" width=\"24px\" height=\"24px\" />](http://godban.github.io/browsers-support-badges/)</br>Chrome | [<img src=\"https://raw.githubusercontent.com/alrra/browser-logos/master/src/safari/safari_48x48.png\" alt=\"Safari\" width=\"24px\" height=\"24px\" />](http://godban.github.io/browsers-support-badges/)</br>Safari |\n| --------- | --------- | --------- | --------- |\n| IE10, IE11, Edge| last 2 versions| last 2 versions| last 2 versions\n\n## License\n\n[MIT](https://github.com/PanJiaChen/vue-admin-template/blob/master/LICENSE) license.\n\nCopyright (c) 2017-present PanJiaChen\n',
        22789503);
