INSERT INTO `repository`
VALUES (10000043, 'shshshsh/aarch64-qemu', 'https://gitee.com/shshshsh/aarch64-qemu.git',
        '# QEMU AArch64 baremetal app example\n\n\n## ENV setup\n+ vscode\n+ C/C++ extension enable && clangd disable\n+ .vscode cfg\n+ qemu support raspi4b\n\n### qemu build\n```\n./configure --target-list=aarch64-softmmu --prefix=/home/pop/work/qemu/qemu-out2\n```\n\n## build\n\n```bash\n$ make\n```\n\n## run\n\n```bash\nqemu-system-aarch64 -cpu cortex-a53 -M virt -nographic -semihosting -kernel aarch64-qemu.bin\n```\n',
        27415141);
