INSERT INTO `repository`
VALUES (10000074, 'shshshsh/xen', 'https://gitee.com/shshshsh/xen.git',
        '#################################################\n__  __            _  _    _  ___\n\\ \\/ /___ _ __   | || |  / |/ _ \\       _ __ ___\n \\  // _ \\ \'_ \\  | || |_ | | (_) |_____| \'__/ __|\n /  \\  __/ | | | |__   _|| |\\__, |_____| | | (__\n/_/\\_\\___|_| |_|    |_|(_)_|  /_/      |_|  \\___|\n\n#################################################\n\nhttps://www.xen.org/\n\nWhat is Xen?\n============\n\nXen is a Virtual Machine Monitor (VMM) originally developed by the\nSystems Research Group of the University of Cambridge Computer\nLaboratory, as part of the UK-EPSRC funded XenoServers project.  Xen\nis freely-distributable Open Source software, released under the GNU\nGPL. Since its initial public release, Xen has grown a large\ndevelopment community, spearheaded by xen.org (https://www.xen.org).\n\nThis file contains some quick-start instructions to install Xen on\nyour system. For more information see https://www.xen.org/ and\nhttps://wiki.xen.org/\n\nQuick-Start Guide\n=================\n\nFirst, this is just a quick-start guide. For more comprehensive\ninformation see the INSTALL file and the Xen wiki at\nhttps://wiki.xenproject.org and in particular\nhttps://wiki.xenproject.org/wiki/Getting_Started.\n\nSecond, there are a number of prerequisites for building a Xen source\nrelease. Make sure you have all the following installed, either by\nvisiting the project webpage or installing a pre-built package\nprovided by your OS distributor:\n    * GNU Make v3.80 or later\n    * C compiler and linker:\n      - For x86:\n        - GCC 4.1.2_20070115 or later\n        - GNU Binutils 2.16.91.0.5 or later\n        or\n        - Clang/LLVM 3.5 or later\n      - For ARM 32-bit:\n        - GCC 4.9 or later\n        - GNU Binutils 2.24 or later\n      - For ARM 64-bit:\n        - GCC 5.1 or later\n        - GNU Binutils 2.24 or later\n    * POSIX compatible awk\n    * Development install of zlib (e.g., zlib-dev)\n    * Development install of Python 2.7 or later (e.g., python-dev)\n    * Development install of curses (e.g., libncurses-dev)\n    * Development install of openssl (e.g., openssl-dev)\n    * Development install of x11 (e.g. xorg-x11-dev)\n    * Development install of uuid (e.g. uuid-dev)\n    * Development install of yajl (e.g. libyajl-dev)\n    * Development install of libaio (e.g. libaio-dev) version 0.3.107 or\n      greater.\n    * Development install of GLib v2.0 (e.g. libglib2.0-dev)\n    * Development install of Pixman (e.g. libpixman-1-dev)\n    * pkg-config\n    * bridge-utils package (/sbin/brctl)\n    * iproute package (/sbin/ip)\n    * GNU bison and GNU flex\n    * ACPI ASL compiler (iasl)\n\nIn addition to the above there are a number of optional build\nprerequisites. Omitting these will cause the related features to be\ndisabled at compile time:\n    * Binary-search capable grep (if building Xen with CET support)\n    * Development install of Ocaml (e.g. ocaml-nox and\n      ocaml-findlib). Required to build ocaml components which\n      includes the alternative ocaml xenstored.\n    * cmake (if building vtpm stub domains)\n    * pandoc, transfig, pod2{man,html,text} for rendering various pieces of\n      documentation into alternative formats\n    * figlet (for generating the traditional Xen start of day banner)\n    * systemd daemon development files\n    * Development install of libnl3 (e.g., libnl-3-200,\n      libnl-3-dev, etc).  Required if network buffering is desired\n      when using Remus with libxl.  See docs/README.remus for detailed\n      information.\n    * 16-bit x86 assembler, loader and compiler for qemu-traditional / rombios\n      (dev86 rpm or bin86 & bcc debs)\n    * Development install of liblzma for rombios\n    * Development install of libbz2, liblzma, liblzo2, and libzstd for DomU\n      kernel decompression.\n\nSecond, you need to acquire a suitable kernel for use in domain 0. If\npossible you should use a kernel provided by your OS distributor. If\nno suitable kernel is available from your OS distributor then refer to\nhttps://wiki.xen.org/wiki/XenDom0Kernels for suggestions for\nsuitable kernels to use.\nIf you are looking to compile a Dom0 kernel from source, please refer to\nhttps://wiki.xen.org/wiki/XenParavirtOps.\n\n[NB. Unless noted otherwise, all the following steps should be\nperformed with root privileges.]\n\n1. Download and untar the source tarball file. This will be a\n   file named xen-unstable-src.tgz, or xen-$version-src.tgz.\n   You can also pull the current version from the git or mercurial\n   repositories at https://xenbits.xen.org/\n\n    # tar xzf xen-unstable-src.tgz\n\n   Assuming you are using the unstable tree, this will\n   untar into xen-unstable. The rest of the instructions\n   use the unstable tree as an example, substitute the\n   version for unstable.\n\n2. cd to xen-unstable (or whatever you sensibly rename it to).\n\n3. For the very first build, or if you want to destroy build trees,\n   perform the following steps:\n\n    # ./configure\n    # make world\n    # make install\n\n   See the documentation in the INSTALL file for more info.\n\n   This will create and install onto the local machine. It will build\n   the xen binary (xen.gz), the tools and the documentation.\n\n   You can override the destination for make install by setting DESTDIR\n   to some value.\n\n4. To rebuild an existing tree without modifying the config:\n    # make dist\n\n   This will build and install xen, tools, and docs into the local dist/\n   directory.\n\n   You can override the destination for make install by setting DISTDIR\n   to some value.\n\n   make install and make dist differ in that make install does the\n   right things for your local machine (installing the appropriate\n   version of udev scripts, for example), but make dist includes all\n   versions of those scripts, so that you can copy the dist directory\n   to another machine and install from that distribution.\n\nxenstore: xenstored and oxenstored\n====================================\n\nXen uses a configuration database called xenstore [0] to maintain configuration\nand status information shared between domains. A daemon is implemented as part\nof xenstore to act as an interface for access to the database for dom0 and\nguests. Two xenstored daemons are supported, one written in C which we refer\nto as the xenstored (sometimes referred to as cxenstored), and another written\nin Ocaml called oxenstored. Details for xenstore and the different\nimplementations can be found on the wiki\'s xenstore reference guide [1] and\nthe xenstored [2] page. You can choose which xenstore you want to enable as\ndefault on a system through configure:\n\n        ./configure --with-xenstored=xenstored\n        ./configure --with-xenstored=oxenstored\n\nBy default oxenstored will be used if the ocaml development tools are found.\nIf you enable oxenstored the xenstored will still be built and installed,\nthe xenstored used can be changed through the configuration file:\n\n/etc/sysconfig/xencommons\nor\n/etc/default/xencommons\n\nYou can change the preferred xenstored you want to use in the configuration\nbut since we cannot stop the daemon a reboot will be required to make the\nchange take effect.\n\n[0] https://wiki.xen.org/wiki/XenStore\n[1] https://wiki.xen.org/wiki/XenStoreReference\n[2] https://wiki.xen.org/wiki/Xenstored\n\nPython Runtime Libraries\n========================\n\nVarious tools, such as pygrub, have the following runtime dependencies:\n\n    * Python 2.7 or later.\n          URL:    https://www.python.org/\n          Debian: python\n\nIntel(R) Trusted Execution Technology Support\n=============================================\n\nIntel\'s technology for safer computing, Intel(R) Trusted Execution Technology\n(Intel(R) TXT), defines platform-level enhancements that provide the building\nblocks for creating trusted platforms.  For more information, see\nhttps://www.intel.com/technology/security/.\n\nIntel(R) TXT support is provided by the Trusted Boot (tboot) module in\nconjunction with minimal logic in the Xen hypervisor.\n\nTboot is an open source, pre- kernel/VMM module that uses Intel(R) TXT to\nperform a measured and verified launch of an OS kernel/VMM.\n\nThe Trusted Boot module is available from\nhttp://sourceforge.net/projects/tboot.  This project hosts the code in a\nmercurial repo at http://tboot.sourceforge.net/hg/tboot.hg and contains\ntarballs of the source.  Instructions in the tboot README describe how\nto modify grub.conf to use tboot to launch Xen.\n',
        36894877);
INSERT INTO `repository`
VALUES (10000075, 'blcok007_admin/ChatGPT-Desktop', 'https://gitee.com/blcok007_admin/ChatGPT-Desktop.git',
        '<a href=\"https://github.com/Synaptrix/ChatGPT-Desktop\">\n  <img src=\"https://socialify.git.ci/Synaptrix/ChatGPT-Desktop/image?description=1&descriptionEditable=%E5%9F%BA%E4%BA%8E%20tauri%20%2Bvue3%20%E5%BC%80%E5%8F%91%E7%9A%84%20ChatGPT%20%E8%B7%A8%E5%B9%B3%E5%8F%B0%E5%AE%A2%E6%88%B7%E7%AB%AF%EF%BC%8C%E5%BF%AB%E6%8D%B7%E9%94%AE%E5%BF%AB%E9%80%9F%E5%94%A4%E9%86%92%E7%AA%97%E5%8F%A3%EF%BC%8C%E9%97%AE%E7%AD%94%E5%BF%AB%E4%BA%BA%E4%B8%80%E6%AD%A5%EF%BC%81&font=Inter&forks=1&logo=https%3A%2F%2Fraw.githubusercontent.com%2FSynaptrix%2FChatGPT-Desktop%2Fmaster%2Fsrc-tauri%2Fassets%2Ficon.png&name=1&owner=1&pattern=Circuit%20Board&stargazers=1&theme=Auto\" alt=\"ChatGPT-Desktop\"/>\n</a>\n\n<div align=center>\n  <br/>\n  <div>\n     中文 | <a href=\"https://github.com/Synaptrix/ChatGPT-Desktop\">English</a> | <a href=\"./README-ES.md\">Español</a>\n  </div>\n  <br/>\n\n  <div>\n    <a href=\"https://github.com/Synaptrix/ChatGPT-Desktop/releases/latest\">\n      <img alt=\"macOS\" src=\"https://img.shields.io/badge/-macOS-black?style=flat-square&logo=apple&logoColor=white\" />\n    </a>\n    <a href=\"https://github.com/Synaptrix/ChatGPT-Desktop/releases/latest\">\n      <img alt=\"Windows\" src=\"https://img.shields.io/badge/-Windows-blue?style=flat-square&logo=windows&logoColor=white\" />\n    </a>\n    <a href=\"https://github.com/Synaptrix/ChatGPT-Desktop/releases/latest\">\n      <img alt=\"Linux\" src=\"https://img.shields.io/badge/-Linux-yellow?style=flat-square&logo=linux&logoColor=white\" />\n    </a>\n  </div>\n\n  <div>\n    <img src=\"https://img.shields.io/github/license/Synaptrix/ChatGPT-Desktop?style=flat-square\" />\n    <img src=\"https://img.shields.io/github/package-json/v/Synaptrix/ChatGPT-Desktop?style=flat-square\" />\n    <img src=\"https://img.shields.io/github/downloads/Synaptrix/ChatGPT-Desktop/total?style=flat-square\" />\n  </div>\n\n   <h3>注意：软件本身不提供 API KEY，需要自行准备</h3>\n</div>\n\n## 为什么选择 ChatGPT-Desktop？\n\n当今社会，智能化、便捷化已经成为趋势。选择 ChatGPT-Desktop，您将享受到以下优势：\n\n- 我们使用 tauri 构建项目，使项目包更加小巧精简，资源占用更少，同时适配多个平台。\n\n- 我们提供了配置代理的功能，您可以通过设置代理来实现更加灵活的网络访问。\n\n- 可以选择让 app 常驻后台，快捷键(支持自定义)一键唤醒，节省时间，提高效率。\n\n- 支持多对话，利用 GPT-3.5-turbo 的最新特性，配合记忆模式，随时继续上一次对话。\n\n- 更便捷的管理和调试 prompt 预设，构建你自己的角色预设库，使得对话更加个性化。\n\n- 内置丰富的导出功能，更加便利的分享结果！\n\n- 软件支持自动更新和手动检查更新的功能，以便大家更方便地更新软件。\n\n- 将所有对话存储到本地，方便随时查阅，留在身边最安心。\n\n- 更多的好玩的功能，有待与你一起探索...\n\n## 下载\n\n- **Mac**: [Apple Silicon](https://github.com/ChatGPT-Desktop/ChatGPT-Desktop/releases/download/v1.0.0/ChatGPT-Desktop_1.0.0_aarch64.dmg) 或者 [Intel](https://github.com/ChatGPT-Desktop/ChatGPT-Desktop/releases/download/v1.0.0/ChatGPT-Desktop_1.0.0_x64.dmg)\n- **Windows**: [全平台](https://github.com/ChatGPT-Desktop/ChatGPT-Desktop/releases/download/v1.0.0/ChatGPT-Desktop_1.0.0_x64_zh-CN.msi)\n- **Linux**: [全平台](https://github.com/ChatGPT-Desktop/ChatGPT-Desktop/releases/download/v1.0.0/chat-gpt-desktop_1.0.0_amd64.deb)\n\n<img src=\'./images/theme.gif\' width=\"100%\" />\n\n## 软件截图\n\n<details>\n<summary>查看详情</summary>\n<img src=\'./images/home.png\' />\n<img src=\'./images/settings.png\' />\n<img src=\'./images/role-1.png\' />\n<img src=\'./images/session-1.png\' />\n<img src=\'./images/session-2.png\' />\n<img src=\'./images/session-3.png\' />\n<img src=\'./images/history.png\' />\n<img src=\'./images/update.png\' />\n</details>\n\n## 常见问题\n\n<details>\n<summary>1. 我所在的地区有网络限制，怎么正常使用？</summary>\n\n可以使用我们提供的[解决方案](https://github.com/ChatGPT-Desktop/ChatGPT-Desktop-Porxy)\n\n详细部署教程：[Discord](https://discord.com/channels/1074429768063262791/1090723974650015857)\n\n</details>\n\n<details>\n<summary>2. MacOS 提示 app 已损坏，无法打开。</summary>\n<img width=\'300\' src=\'./images/problem-1.png\' />\n\n参考 huazai 大佬的[解决办法](https://zhuanlan.zhihu.com/p/135948430)\n\n</details>\n\n## 如何贡献\n\n### 项目依赖\n\n- [Rust 环境](https://tauri.app/v1/guides/getting-started/prerequisites/): 请自行根据官网步骤安装 rust 环境\n- [Node.js](https://nodejs.org/en/): 用于运行项目\n\n#### 下载依赖\n\n```shell\nnpm install\n```\n\n#### 启动应用\n\n```shell\nnpm run tauri dev\n```\n\n#### 打包应用\n\n##### 如果需要打包后进行调试，请在以下命令后面加上 `--debug`\n\n```shell\nnpm run tauri build\n```\n\n#### 生成应用图标，请自行替换`src-tauri/assets/icon.png` 文件，仅支持 `png` 格式\n\n```shell\nnpm run build:icon\n```\n\n#### 也可以使用 `yarn` 或者 `pnpm` 等等...\n\n欢迎任何形式的贡献，包括但不限于：\n\n- 提交 Issue\n- 提交 Pull request\n- 提交 Feature request\n- 提交 Bug report\n- 提交文档校订\n- 提交其他任何形式的贡献\n\n## Contact\n\n- [Discord](https://discord.gg/jg4waryfA6)\n\n## Star History\n\n[![Star History Chart](https://api.star-history.com/svg?repos=Synaptrix/ChatGPT-Desktop&type=Date)](https://star-history.com/#Synaptrix/ChatGPT-Desktop&Date)\n\n## Contributors\n\n<a href=\"https://github.com/Synaptrix/ChatGPT-Desktop/graphs/contributors\">\n  <img src=\"https://contrib.rocks/image?repo=Synaptrix/ChatGPT-Desktop\" />\n</a>\n\n## License\n\n[MIT License](./LICENSE)\n',
        35456885);
INSERT INTO `repository`
VALUES (10000076, 'blcok007_admin/ChestnutCMS', 'https://gitee.com/blcok007_admin/ChestnutCMS.git',
        '# ChestnutCMS v1.3.21\n\n### 系统简介\n\nChestnutCMS是前后端分离的企业级内容管理系统。项目基于[RuoYi-Vue](https://gitee.com/y_project/RuoYi-Vue)重构，集成[SaToken](https://gitee.com/dromara/sa-token)用户权限，[xxl-job](https://gitee.com/xuxueli0323/xxl-job)任务调度。支持站群管理、多平台静态化、元数据模型扩展、轻松组织各种复杂内容形态、多语言、全文检索。\n\n### 系统预览\n\n后台预览地址：<http://admin.1000mz.com>\n\n账号：demo / a123456\n\n企业站演示地址：<http://swikoon.1000mz.com>\n\n> 企业演示站的静态资源已提交到仓库[chestnut-cms-wwwroot](https://gitee.com/liweiyi/chestnut-cms-wwwroot)。\n\n资讯站演示地址：<http://news.1000mz.com>（会员演示账号：xxx333@126.com / a123456）\n\n图片站演示地址：<http://tpz.1000mz.com>\n\n\n### 开发环境\n- JDK 17\n- Maven 3.8\n- MySQL 8.0\n- Redis 6.x\n\n### 主要技术框架\n\n| 技术框架              | 版本      | 应用说明    |\n|-------------------|---------|---------|\n| Spring Boot       | 3.1.5   | 基础开发框架  |\n| Spring Boot Admin | 3.1.7   | 监控框架    |\n| Mybatis Plus      | 3.5.3.2 | ORM框架   |\n| Flyway            | 9.22.3  | 数据库版本管理 |\n| Yitter            | 1.0.6   | 雪花ID    |\n| Redisson          | 3.24.1  | 分布式锁    |\n| FreeMarker        | 2.3.32  | 模板引擎    |\n| Sa-Token          | 1.37.0  | 权限认证    |\n| Xxl-Job           | 2.4.0   | 任务调度    |\n| Lombok            | 1.18.20 | 你懂的     |\n\n### 相关文档\n\n\n- [Wiki-快速上手](https://gitee.com/liweiyi/ChestnutCMS/wikis/%E5%BF%AB%E9%80%9F%E5%BC%80%E5%A7%8B)\n- [WiKi-常用配置](https://gitee.com/liweiyi/ChestnutCMS/wikis/%E5%B8%B8%E7%94%A8%E9%85%8D%E7%BD%AE%E8%AF%B4%E6%98%8E)\n- [WiKi-Docker部署说明](https://gitee.com/liweiyi/ChestnutCMS/wikis/Docker%E9%83%A8%E7%BD%B2%E8%AF%B4%E6%98%8E)\n- [WiKi-站点访问配置](https://gitee.com/liweiyi/ChestnutCMS/wikis/%E7%AB%99%E7%82%B9%E8%AE%BF%E9%97%AE%E9%85%8D%E7%BD%AE)\n- [WiKi-使用手册](https://gitee.com/liweiyi/ChestnutCMS/wikis/%E7%B3%BB%E7%BB%9F%E4%BD%BF%E7%94%A8%E6%89%8B%E5%86%8C/%E5%BB%BA%E7%AB%99%E6%B5%81%E7%A8%8B)\n- [WiKi-模板手册](https://gitee.com/liweiyi/ChestnutCMS/wikis/%E6%A8%A1%E6%9D%BF%E6%89%8B%E5%86%8C/%E6%A8%A1%E6%9D%BF%E5%85%A8%E5%B1%80%E5%8F%98%E9%87%8F%E8%AF%B4%E6%98%8E)\n- [WiKi-二次开发手册](https://gitee.com/liweiyi/ChestnutCMS/wikis/%E4%BA%8C%E6%AC%A1%E5%BC%80%E5%8F%91%E6%89%8B%E5%86%8C/%E5%AE%9A%E6%97%B6%E4%BB%BB%E5%8A%A1)\n- [WiKi-常见问题](https://gitee.com/liweiyi/ChestnutCMS/wikis/%E5%B8%B8%E8%A7%81%E9%97%AE%E9%A2%98)\n- [WiKi-版权声明](https://gitee.com/liweiyi/ChestnutCMS/wikis/%E7%89%88%E6%9D%83%E5%A3%B0%E6%98%8E)\n- [WiKi-免责声明](https://gitee.com/liweiyi/ChestnutCMS/wikis/%E5%85%8D%E8%B4%A3%E5%A3%B0%E6%98%8E)\n- [WiKi-版本变更日志](https://gitee.com/liweiyi/ChestnutCMS/wikis/%E7%89%88%E6%9C%AC%E5%8F%98%E6%9B%B4%E6%97%A5%E5%BF%97)\n\n### 功能模块\n\n| 模块           | 简介                                           |\n|--------------|----------------------------------------------|\n| 站点管理         | 多站点，支持图片水印、标题查重、扩展模型等扩展配置                    |\n| 栏目管理         | 普通栏目+链接栏目，扩展配置优先级高于站点扩展配置                    |\n| 内容管理         | 内容类型：文章+图片集+音视频集，页面部件：动态自定义区块+广告，内容回收站       |\n| 资源管理         | 图片、音视频等各类静态资源管理，支持OSS/COS/MinIO对象存储          |\n| 发布通道         | 支持多通道不同类型静态文件发布，可同时发布到PC、H5，html、json等       |\n| 模板管理         | 静态化模板，支持在线编辑                                 |\n| 模板指令         | FreeMarker自定义标签及模板函数的参数及用法说明                 |\n| 文件管理         | 当前站点资源目录及发布通道静态化目录管理，支持文本在线编辑                |\n| 扩展模型         | 站点、栏目及内容的动态模型扩展，系统默认数据表保存，支持自定义              |\n| 词汇管理         | 热词、TAG词、敏感词、易错词                              |\n| 内容索引         | 默认支持ElasticSearch+IK创建内容索引，支持标题内容全文检索        |\n| 检索词库         | 自定义检索词库，支持扩展词和停用词动态扩展                        |\n| 检索日志         | 用户搜索的日志记录，支持一键加入扩展词库                         |\n| 友链管理         | 友情链接                                         |\n| 广告管理         | 广告基于页面部件扩展的简单广告功能，支持权重及上下线时间配置，支持广告点击/展现日志统计 |\n| 评论管理         | 基础功能模块                                       |\n| 调查问卷         | 基础功能模块，默认支持文字类型单选、多选、输入                      |\n| 自定义表单        | 基于元数据模块扩展，支持模板标签                             |\n| 会员管理         | 支持自定义会员等级，等级经验值来源动态配置                        |\n| 访问统计         | 对接百度统计API                                    |\n| 用户管理         | 后台用户管理，支持用户独立权限配置                            |\n| 机构管理         | 多级系统组织机构（公司、部门、小组）                           |\n| 角色管理         | 支持按角色分配菜单权限、站点和栏目相关操作权限配置                    |\n| 岗位管理         | 配置系统用户所属担任职务                                 |\n| 菜单管理         | 配置系统菜单，操作权限，按钮权限标识等                          |\n| 字典管理         | 对系统中经常使用的一些固定的数据进行维护，代码层面定义                  |\n| 参数管理         | 对系统动态配置常用参数，代码层面定义                           |\n| 通知公告         | 系统通知公告信息发布维护                                 |\n| 安全配置         | 密码强度、密码过期、首次登陆强制修改、登陆异常策略配置                  |\n| 国际化          | 为菜单等动态数据国际化配置提供基础支持，可覆盖后台代码配置                |\n| 安全配置         | 密码强度、密码过期、首次登陆强制修改、登陆异常策略配置                  |\n| 系统日志         | 统一日志管理，支持扩展                                  |\n| 操作日志         | 系统操作日志扩展，记录操作参数、异常信息及请求耗时                    |\n| 登录日志         | 系统登录日志扩展，记录用户登录日志，包含登录异常                     |\n| 在线用户         | 当前系统中活跃用户状态监控，支持踢下线                          |\n| 任务调度         | 基于XXL-JOB的分布式任务调度                            |\n| 定时任务         | 基于Spring的TaskScheduler实现的单机定时任务              |\n| 异步任务         | 异步任务状态查看，支持手动结束                              |\n| 服务监控         | 监视当前系统CPU、内存、磁盘、堆栈等相关信息                      |\n| 缓存监控         | 对系统的缓存信息查询，命令统计等                             |\n| GroovyScript | 支持Groovy脚本在线执行                               |\n\n### 开源协议补充说明\n\n1. ChestnutCMS 遵循《Apache-2.0开源协议》，使用本系统不得用于违反国家有关政策的相关软件和应用。\n2. 系统可免费商用，但是必须包含原始版权声明和许可声明（项目根目录下的LICENSE文件不可修改或删除），不可移除或修改后台登录页面底部的版权申明“Copyright © 2022-2023 ChestnutCMS (1000mz.com) All Rights Reserved.”。\n3. 本项目所包含的第三方源码版权信息需另行标注。\n\n### QQ交流群\n群①：568506424\n群②：643215654\n统一入群口令：举个栗子\n\n如果本项目对您有一丢丢小帮助 :kissing_heart: 点个小星星吧 :star2:',
        31863469);
INSERT INTO `repository`
VALUES (10000077, 'blcok007_admin/JeeWMSapp-uni', 'https://gitee.com/blcok007_admin/JeeWMSapp-uni.git',
        '\n#### 提示\n\n- 添加新的页面 在pages.json添加完了以后 还需要到 common/router/modules/routes 页面去添加\n- 一共有三个套的页面  第一版首页已经被改掉了  第二版跟第三版在main.js去修改 Vue.prototype.$systemType 的值就可以\n- 第二套页面全部都在pages/pageFrame文件夹中 \n- 第三套页面全部都在pages/zx文件夹中 \n- 修改请求地址在common/router/config.service.js修改',
        37462069);
INSERT INTO `repository`
VALUES (10000078, 'blcok007_admin/MicroCommunity', 'https://gitee.com/blcok007_admin/MicroCommunity.git',
        '[english](Readme_en.md)|[中文](Readme_cn.md)\n## 说明\n HC小区管理系统是一套saas物业管理的系统，包括 房产、业主、 费用 （可以线上缴费）、报修（可以线上报修）、投诉建议、采购、巡检、停车、门径、道闸、监控、工作流、问卷和公告等功能。\n\n目前很多地方商用超过一年半时间 欢饮直接使用或者推广使用\n \n 相关代码：<br/><br/>\n 1、[物业系统前端](https://gitee.com/java110/MicroCommunityWeb) : 物业员工使用电脑端<br/>\n 2、[物业系统后端](https://gitee.com/wuxw7/MicroCommunity): 核心业务处理端<br/>\n 3、[业主手机端](https://gitee.com/java110/WechatOwnerService): 提供用户使用，包括投诉 建议，缴费、报修 等<br/>\n 4、[物业手机版](https://gitee.com/java110/PropertyApp): 物业员工使用手机端<br/>\n\n## 如何安装\n\n1、[开发环境安装](docs/installHcDev.md) <br/>\n2、[生产环境安装](docs/installHcProd.md)<br/>\n3、[springboot方式启动](docs/installSpringboot.md)<br/>\n\n## 如何使用\n\n[操作手册](http://bbs.homecommunity.cn/document.html?docId=102022031484710001)\n\n   \n## 产品\n\n1、手机端演示环境\n\n   ![image](docs/img/hc.png)\n\n2、电脑端<br/>\n地址：http://demo.homecommunity.cn <br/>\n管理员账号：admin/admin<br/>\n物业演示账号:wuxw/admin<br/>\n开发者账号：dev/密码自己修改 [如何修改](http://bbs.homecommunity.cn/pages/bbs/topic.html?topicId=102021110520080050)\n    \n## 系统功能（function） \n\n   ![image](docs/img/func.png)\n   \n   主要系统功能请查看\n     \n   [功能清单](http://bbs.homecommunity.cn/pages/bbs/topic.html?topicId=102022042459860343)\n  \n## 运行效果（view）\n1.在浏览器输入 http://localhost:3000/ 如下图\n\n![image](docs/img/login.png)\n\n    用户名为 wuxw 密码为 admin  如下图\n\n    点击登录，进入如下图：\n\n![image](docs/img/0004.png)\n\n![image](docs/img/index.png)\n\n![image](docs/img/business.png)\n\n![image](docs/img/owner.png)\n\n![image](docs/img/phone.png)\n\n## 参与贡献\n\n您可以fork 代码后，commit后 pull request合并代码\n\n联系作者：17797173942（微信号）\n\nQQ交流群8：780056134\n\n\n\n',
        39087138);
INSERT INTO `repository`
VALUES (10000079, 'blcok007_admin/ModernWMS', 'https://gitee.com/blcok007_admin/ModernWMS.git',
        '# ModernWMS - 仓库管理系统 \r\n\r\n<div align=\"center\">\r\n  <img src=\"logo.png\" alt=\"ModernWMS logo\" width=\"200\" height=\"auto\" />\r\n  <h1>ModernWMS</h1>\r\n  <p>开源的简易完整的仓库管理系统</p>\r\n\r\n<!-- Badges -->\r\n[![License: Apache2.0](https://img.shields.io/badge/license-Apache2.0-orange.svg)](https://opensource.org/license/apache-2-0/)\r\n![Release Version (latest Version)](https://img.shields.io/github/v/release/fjykTec/ModernWMS?color=orange&include_prereleases)\r\n![QR Code Support](https://img.shields.io/badge/QR--Code-Support-orange.svg)\r\n![Docker Support](https://img.shields.io/badge/Docker-Support-orange.svg)\r\n![i18n Support](https://img.shields.io/badge/i18n-Support-orange.svg)\r\n[![MySQL8](https://img.shields.io/badge/MySQL8.0%2B-Support-orange)](https://www.mysql.com/downloads/)\r\n[![SQL Server](https://img.shields.io/badge/SQL%20Server2017%2B-Support-orange)](https://www.mysql.com/downloads/)\r\n[![PostgreSQL](https://img.shields.io/badge/PostgreSQL12-Support-orange)](https://www.mysql.com/downloads/)\r\n\r\n![repo size](https://img.shields.io/github/repo-size/fjykTec/ModernWMS)\r\n![GitHub commit activity](https://img.shields.io/github/commit-activity/m/fjykTec/ModernWMS)\r\n<!--![Contributors](https://img.shields.io/github/contributors/fjykTec/ModernWMS?color=blue) -->\r\n\r\n![GitHub Org\'s stars](https://img.shields.io/github/stars/fjykTec/ModernWMS?style=social)\r\n![GitHub Follows](https://img.shields.io/github/followers/ModernWMS?style=social)\r\n![GitHub Forks](https://img.shields.io/github/forks/fjykTec/ModernWMS?style=social)\r\n![GitHub Watch](https://img.shields.io/github/watchers/fjykTec/ModernWMS?style=social)\r\n![Gitee Stars](https://gitee.com/modernwms/ModernWMS/badge/star.svg?theme=social)\r\n![Gitee Forks](https://gitee.com/modernwms/ModernWMS/badge/fork.svg?theme=social)\r\n\r\n![.NET](https://img.shields.io/badge/.NET-7.0.0-green)\r\n![Vuetify Cli](https://img.shields.io/badge/Vuetify/cli-3.0.4-green)\r\n![Vue](https://img.shields.io/badge/Vue-3.2.45-green)\r\n![TypeScript](https://img.shields.io/badge/TypeScript-4.1.2-green)\r\n![VXE Table](https://img.shields.io/badge/VXETable-4.3.7-green)\r\n![Vite](https://img.shields.io/badge/Vite-4.0.0-green)\r\n![NodeJS](https://img.shields.io/badge/NodeJS-16.13.1-green)\r\n</div>\r\n<div align=\"center\">\r\n  <h3>\r\n  <a href=\"https://gitee.com/modernwms/ModernWMS/blob/master/README.md\">English Document</a>\r\n  </h3>\r\n  <h3>\r\n  <a href=\"https://modernwms.ikeyly.com\">官网首页</a>\r\n  </h3>\r\n</div>\r\n\r\n# 目录 \r\n\r\n- [ModernWMS - 仓库管理系统](#modernwms---仓库管理系统)\r\n- [目录](#目录)\r\n  - [介绍](#介绍)\r\n  - [必要条件](#必要条件)\r\n    - [Linux OS](#linux-os)\r\n    - [Windows OS](#windows-os)\r\n  - [安装](#安装)\r\n    - [Linux](#linux)\r\n    - [Windows](#windows)\r\n  - [使用方法](#使用方法)\r\n  - [联系我们](#联系我们)\r\n  - [版权信息](#版权信息)\r\n  - [特别声明](#特别声明)\r\n  - [捐赠](#捐赠)\r\n\r\n\r\n## 介绍\r\n  该库存管理系统是，我们从多年ERP系统研发中总结出来的一套针对小型物流仓储供应链流程。 在工作过程中我们很多的中小企业，由于IT预算有限，所以无法用上适合他们的系统，却又实实在在存在仓储管理方面的需求，以此我们开始了这个项目。 为了帮助一些有需要的用户。\r\n\r\n## 必要条件\r\n\r\n### Linux OS\r\n\r\n+ Ubuntu 18.04(LTS),20.04(LTS),22.04(LTS)\r\n+ CentOS Stream 8,9\r\n+ RHEL 8(8.7),9(9.1)\r\n+ Debian 10,11\r\n+ openSUSE 15\r\n\r\n### Windows OS\r\n\r\n+ Windows 10 版本 1607 或更高版本\r\n+ Windows Server 2012 或更高版本\r\n\r\n## 安装\r\n\r\n### Linux\r\n\r\n+ 下载源码后编译\r\n  + 第一步，下载源码\r\n\r\n  ```bash\r\n  cd /tmp/ && wget https://gitee.com/modernwms/ModernWMS/repository/archive/master.zip\r\n  ```  \r\n\r\n  + 第二步，安装.NET SDK 和 NodeJS\r\n\r\n  ```bash\r\n  wget https://packages.microsoft.com/config/ubuntu/20.04/packages-microsoft-prod.deb -O packages-microsoft-prod.deb\r\n  sudo dpkg -i packages-microsoft-prod.deb\r\n  sudo apt-get update && sudo apt-get install -y dotnet-sdk-7.0\r\n  curl -fsSL https://deb.nodesource.com/setup_16.x | sudo -E bash -\r\n  sudo apt install -y nodejs\r\n  sudo apt-get install gcc g++ make\r\n  sudo npm install -g yarn\r\n  ```  \r\n\r\n  + 第三步，编译前端和后端\r\n\r\n  ```bash\r\n  sudo apt install unzip\r\n  cd /tmp/ && unzip master.zip && cd ./ModernWMS-master\r\n  mkdir -p /ModernWMS/frontend/ /ModernWMS/backend/\r\n  cd /tmp/ModernWMS-master/frontend/ \r\n  sed -i \'s#http://127.0.0.1#http://前部署服务器的IP地址#g\' ./.env.production\r\n  yarn && yarn build && cp -rf /tmp/ModernWMS-master/frontend/dist/* /ModernWMS/frontend/\r\n  cd /tmp/ModernWMS-master/backend/ && sudo dotnet publish && cp -rf /tmp/ModernWMS-master/backend/ModernWMS/bin/Debug/net7.0/publish/* /ModernWMS/backend/\r\n  cp -rf /tmp/ModernWMS-master/backend/ModernWMS/wms.db /ModernWMS/backend/\r\n  ```  \r\n\r\n  + 第四步，安装nginx\r\n\r\n  ```bash\r\n  cd /tmp/ && wget http://nginx.org/download/nginx-1.18.0.tar.gz \r\n  tar -zxvf nginx-1.18.0.tar.gz && cd nginx-1.18.0\r\n  ./configure --prefix=/etc/nginx --with-http_secure_link_module --with-http_stub_status_module --with-http_realip_module --without-http_rewrite_module --without-http_gzip_module\r\n  make && make install\r\n  cp -rf /ModernWMS/frontend/* /etc/nginx/html/\r\n  nohup /etc/nginx/sbin/nginx -g \'daemon off;\' &\r\n  cd /ModernWMS/backend/ && dotnet ModernWMS.dll --urls http://0.0.0.0:20011\r\n  ```  \r\n### Windows\r\n\r\n+ 下载源码后编译部署\r\n  + 第一步，下载源码\r\n  ```PowerShell\r\n  cd C:\\\r\n  wget -Uri https://gitee.com/modernwms/ModernWMS/repository/archive/master.zip  -OutFile master.zip\r\n  Expand-Archive -Path C:\\master.zip -DestinationPath C:\\\r\n  ```\r\n  + 第二步，安装.NET SDK 和 NodeJS\r\n  ```CMD\r\n  wget -Uri https://download.visualstudio.microsoft.com/download/pr/35660869-0942-4c5d-8692-6e0d4040137a/4921a36b578d8358dac4c27598519832/dotnet-sdk-7.0.101-win-x64.exe  -OutFile dotnet-sdk-7.0.101-win-x64.exe\r\n  .\\dotnet-sdk-7.0.101-win-x64.exe /install /quiet /norestart\r\n  wget -Uri https://nodejs.org/dist/v16.13.1/node-v16.13.1-x64.msi  -OutFile node-v16.13.1-x64.msi\r\n  msiexec /i .\\node-v16.13.1-x64.msi /passive /norestart\r\n  npm install -g yarn\r\n  ```\r\n  + 第三步，编译前端和后端\r\n  ```\r\n  md C:\\ModernWMS\\frontend\\\r\n  md C:\\ModernWMS\\backend\\\r\n  cd C:\\ModernWMS-master\\backend\r\n  dotnet publish \r\n  copy-item -path \"C:\\ModernWMS-master\\backend\\ModernWMS\\bin\\Debug\\net7.0\\publish\\*\" -destination \"C:\\ModernWMS\\backend\\\" -recurse\r\n  copy-Item \"C:\\ModernWMS-master\\backend\\ModernWMS\\wms.db\" -Destination \"C:\\ModernWMS\\backend\\\"\r\n  cd C:\\ModernWMS-master\\frontend  \r\n  yarn\r\n  yarn build \r\n  copy-item -path \"C:\\ModernWMS-master\\frontend\\dist\\*\" -destination \"C:\\ModernWMS\\frontend\\\" -recurse\r\n  ```\r\n  + 第四步，安装nginx并启动\r\n  ```\r\n  cd C:\\\r\n  wget -Uri http://nginx.org/download/nginx-1.16.1.zip -OutFile nginx-1.16.1.zip\r\n  Expand-Archive -Path C:\\nginx-1.16.1.zip -DestinationPath C:\\\r\n  copy-item -path \"C:\\ModernWMS\\frontend\\*\" -destination \"C:\\nginx-1.16.1\\html\\\" -recurse\r\n  cd C:\\nginx-1.16.1\\\r\n  start nginx.exe\r\n  cd C:\\ModernWMS\\backend\\\r\n  dotnet ModernWMS.dll --urls http://0.0.0.0:20011\r\n  ```\r\n\r\n\r\n## 使用方法\r\n\r\n  ```shell\r\n  打开浏览器，进入：http://127.0.0.1 或者http://部署电脑的IP地址  \r\n  \r\n  初始账号: admin 密码: 1\r\n  ```\r\n  <h4>\r\n    <a href=\"https://wmsonline.ikeyly.com\">体验地址入口</a>\r\n  </h4> \r\n\r\n  <img src=\"image0.png\" alt=\"image0\" height=\"auto\" />\r\n\r\n  <img src=\"image1.png\" alt=\"image1\" height=\"auto\" />\r\n  \r\n  <img src=\"image2.png\" alt=\"image2\" height=\"auto\" />\r\n\r\n## 联系我们\r\n\r\n<h4>\r\n  <a href=\"https://gitee.com/leucoon/vue-element-plus-admin/issues/new?issue%5Bassignee_id%5D=0&issue%5Bmilestone_id%5D=0\">提交一个Bug</a>\r\n</h4>\r\n<h4>\r\n  <a href=\"https://gitee.com/leucoon/vue-element-plus-admin/issues/new?issue%5Bassignee_id%5D=0&issue%5Bmilestone_id%5D=0\">提交一个建议</a>\r\n</h4>\r\n\r\n## 版权信息\r\n该项目使用的是 [Apache2.0](https://opensource.org/license/apache-2-0/) 协议. 详情查阅[LICENSE.txt](https://gitee.com/modernwms/ModernWMS/blob/master/LICENSE).必须遵守此协议。\r\n\r\n## 特别声明\r\n\r\n本项目已加入 [dotNET China](https://gitee.com/dotnetchina)  组织。<br/>\r\n\r\n![dotnetchina](https://gitee.com/dotnetchina/home/raw/master/assets/dotnetchina-raw.png \"dotNET China LOGO\")\r\n\r\n## 捐赠\r\n\r\n如果您觉得我的开源库可以帮到您，请我们的作者喝杯咖啡吧，您的支持将鼓励我们继续创作。\r\n\r\n<img src=\"alipay.jpg\" alt=\"image3\" height=\"auto\" />\r\n<img src=\"wechat.jpg\" alt=\"image4\" height=\"auto\" />',
        37462292);
INSERT INTO `repository`
VALUES (10000080, 'blcok007_admin/QAnything', 'https://gitee.com/blcok007_admin/QAnything.git',
        '<div align=\"center\">\n\n  <a href=\"https://github.com/netease-youdao/QAnything\">\n    <!-- Please provide path to your logo here -->\n    <img src=\"docs/images/qanything_logo.png\" alt=\"Logo\" width=\"911\" height=\"175\">\n  </a>\n\n# **Q**uestion and **A**nswer based on **Anything**\n\n<p align=\"center\">\n  <a href=\"./README.md\">English</a> |\n  <a href=\"./README_zh.md\">简体中文</a>\n</p>\n\n</div>\n\n<div align=\"center\">\n\n<a href=\"https://qanything.ai\"><img src=\"https://img.shields.io/badge/%E5%9C%A8%E7%BA%BF%E4%BD%93%E9%AA%8C-QAnything-purple\"></a>\n&nbsp;&nbsp;&nbsp;&nbsp;\n<a href=\"https://read.youdao.com#/home\"><img src=\"https://img.shields.io/badge/%E5%9C%A8%E7%BA%BF%E4%BD%93%E9%AA%8C-有道速读-purple\"></a>\n&nbsp;&nbsp;&nbsp;&nbsp;\n\n<a href=\"./LICENSE\"><img src=\"https://img.shields.io/badge/license-Apache--2.0-yellow\"></a>\n&nbsp;&nbsp;&nbsp;&nbsp;\n<a href=\"https://github.com/netease-youdao/QAnything/pulls\"><img src=\"https://img.shields.io/badge/PRs-welcome-red\"></a>\n&nbsp;&nbsp;&nbsp;&nbsp;\n<a href=\"https://twitter.com/YDopensource\"><img src=\"https://img.shields.io/badge/follow-%40YDOpenSource-1DA1F2?logo=twitter&style={style}\"></a>\n&nbsp;&nbsp;&nbsp;&nbsp;\n\n</div>\n\n<details open=\"open\">\n<summary>目 录</summary>\n\n- [什么是QAnything](#什么是qanything)\n  - [特点](#特点)\n  - [架构](#架构)\n- [最近更新](#-最近更新)\n- [开始之前](#开始之前)\n- [开始](#开始)\n  - [安装方式](#安装方式)\n  - [纯Python环境安装](#纯python环境安装)\n  - [docker环境安装](#docker环境安装)\n  - [断网安装](#断网安装)\n- [常见问题](#常见问题)\n- [使用](#使用)\n- [路线图&反馈](#%EF%B8%8F-路线图--反馈)\n- [交流&支持](#交流--支持)\n- [协议](#协议)\n- [Acknowledgements](#acknowledgements)\n\n</details>\n\n\n# 什么是QAnything？\n**QAnything** (**Q**uestion and **A**nswer based on **Anything**) 是致力于支持任意格式文件或数据库的本地知识库问答系统，可断网安装使用。\n\n您的任何格式的本地文件都可以往里扔，即可获得准确、快速、靠谱的问答体验。\n\n目前已支持格式: **PDF(pdf)**，**Word(docx)**，**PPT(pptx)**，**XLS(xlsx)**，**Markdown(md)**，**电子邮件(eml)**，**TXT(txt)**，**图片(jpg，jpeg，png)**，**CSV(csv)**，**网页链接(html)**，更多格式，敬请期待...\n\n## 特点\n- 数据安全，支持全程拔网线安装使用。\n- 支持跨语种问答，中英文问答随意切换，无所谓文件是什么语种。\n- 支持海量数据问答，两阶段向量排序，解决了大规模数据检索退化的问题，数据越多，效果越好。\n- 高性能生产级系统，可直接部署企业应用。\n- 易用性，无需繁琐的配置，一键安装部署，拿来就用。\n- 支持选择多知识库问答。\n\n## 架构\n<div align=\"center\">\n<img src=\"docs/images/qanything_arch.png\" width = \"700\" alt=\"qanything_system\" align=center />\n</div>\n\n### 为什么是两阶段检索?\n知识库数据量大的场景下两阶段优势非常明显，如果只用一阶段embedding检索，随着数据量增大会出现检索退化的问题，如下图中绿线所示，二阶段rerank重排后能实现准确率稳定增长，即**数据越多，效果越好**。\n\n<div align=\"center\">\n<img src=\"docs/images/two_stage_retrieval.jpg\" width = \"500\" alt=\"two stage retrievaal\" align=center />\n</div>\n\nQAnything使用的检索组件[BCEmbedding](https://github.com/netease-youdao/BCEmbedding)有非常强悍的双语和跨语种能力，能消除语义检索里面的中英语言之间的差异，从而实现：\n- **强大的双语和跨语种语义表征能力【<a href=\"https://github.com/netease-youdao/BCEmbedding/tree/master?tab=readme-ov-file#semantic-representation-evaluations-in-mteb\" target=\"_Self\">基于MTEB的语义表征评测指标</a>】。**\n- **基于LlamaIndex的RAG评测，表现SOTA【<a href=\"https://github.com/netease-youdao/BCEmbedding/tree/master?tab=readme-ov-file#rag-evaluations-in-llamaindex\" target=\"_Self\">基于LlamaIndex的RAG评测指标</a>】。**\n\n\n### 一阶段检索（embedding）\n| 模型名称 | Retrieval | STS | PairClassification | Classification | Reranking | Clustering | 平均 |  \n|:-------------------------------|:--------:|:--------:|:--------:|:--------:|:--------:|:--------:|:--------:|  \n| bge-base-en-v1.5 | 37.14 | 55.06 | 75.45 | 59.73 | 43.05 | 37.74 | 47.20 |  \n| bge-base-zh-v1.5 | 47.60 | 63.72 | 77.40 | 63.38 | 54.85 | 32.56 | 53.60 |  \n| bge-large-en-v1.5 | 37.15 | 54.09 | 75.00 | 59.24 | 42.68 | 37.32 | 46.82 |  \n| bge-large-zh-v1.5 | 47.54 | 64.73 | **79.14** | 64.19 | 55.88 | 33.26 | 54.21 |  \n| jina-embeddings-v2-base-en | 31.58 | 54.28 | 74.84 | 58.42 | 41.16 | 34.67 | 44.29 |  \n| m3e-base | 46.29 | 63.93 | 71.84 | 64.08 | 52.38 | 37.84 | 53.54 |  \n| m3e-large | 34.85 | 59.74 | 67.69 | 60.07 | 48.99 | 31.62 | 46.78 |  \n| ***bce-embedding-base_v1*** | **57.60** | **65.73** | 74.96 | **69.00** | **57.29** | **38.95** | ***59.43*** |  \n\n- 更详细的评测结果详见[Embedding模型指标汇总](https://github.com/netease-youdao/BCEmbedding/blob/master/Docs/EvaluationSummary/embedding_eval_summary.md)。\n\n### 二阶段检索（rerank）\n| 模型名称 | Reranking | 平均 |  \n|:-------------------------------|:--------:|:--------:|  \n| bge-reranker-base | 57.78 | 57.78 |  \n| bge-reranker-large | 59.69 | 59.69 |  \n| ***bce-reranker-base_v1*** | **60.06** | ***60.06*** |  \n\n- 更详细的评测结果详见[Reranker模型指标汇总](https://github.com/netease-youdao/BCEmbedding/blob/master/Docs/EvaluationSummary/reranker_eval_summary.md)\n\n### 基于LlamaIndex的RAG评测（embedding and rerank）\n\n<img src=\"https://github.com/netease-youdao/BCEmbedding/blob/master/Docs/assets/rag_eval_multiple_domains_summary.jpg\">\n\n***NOTE:***\n\n- 在WithoutReranker列中，我们的bce-embedding-base_v1模型优于所有其他embedding模型。\n- 在固定embedding模型的情况下，我们的bce-reranker-base_v1模型达到了最佳表现。\n- **bce-embedding-base_v1和bce-reranker-base_v1的组合是SOTA。**\n- 如果想单独使用embedding和rerank请参阅：[BCEmbedding](https://github.com/netease-youdao/BCEmbedding)\n\n### LLM\n\n开源版本QAnything的大模型基于通义千问，并在大量专业问答数据集上进行微调；在千问的基础上大大加强了问答的能力。\n如果需要商用请遵循千问的license，具体请参阅：[通义千问](https://github.com/QwenLM/Qwen)\n\n# 🚀 最近更新 \n- ***2024-04-03***: **支持在纯Python环境中安装；支持混合检索。** - 详见👉 [v1.3.0](https://github.com/netease-youdao/QAnything/releases/tag/v1.3.0)\n- ***2024-01-29***: **支持自定义大模型，包括OpenAI API和其他开源大模型，GPU需求最低降至GTX 1050Ti，极大提升部署，调试等方面的用户体验** - 详见👉 [v1.2.0](https://github.com/netease-youdao/QAnything/releases/tag/v1.2.0)\n- ***2024-01-23***: **默认开启rerank，修复在windows上启动时存在的各类问题** - 详见👉 [v1.1.1](https://github.com/netease-youdao/QAnything/releases/tag/v1.1.1)\n- ***2024-01-18***: **支持一键启动，支持windows部署，提升pdf，xlsx，html解析效果** - 详见👉 [v1.1.0](https://github.com/netease-youdao/QAnything/releases/tag/v1.1.0)\n\n# 开始之前\n**在GitHub上加星，即可立即收到新版本的通知！**\n![star_us](https://github.com/netease-youdao/QAnything/assets/29041332/fd5e5926-b9b2-4675-9f60-6cdcaca18e14)\n* [🏄 在线试用QAnything](https://qanything.ai)\n* [📚 在线试用有道速读](https://read.youdao.com)\n* [🛠️ 想只使用BCEmbedding(embedding & rerank)](https://github.com/netease-youdao/BCEmbedding)\n* [📖 常见问题](FAQ_zh.md)\n* [👂️需求反馈 | 让我听见你的声音](https://qanything.canny.io/feature-requests)\n\n\n# 开始\n## 安装方式\n我们提供三种安装方式：\n- [纯python环境安装](#下载安装纯python环境)\n- [docker安装](#installationdocker)\n- [断网安装](#断网安装)\n\n不同安装方式对应的特性如下表:\n\n| 特性                | [纯python环境安装](#纯python环境安装)   |    [docker安装](#docker环境安装)     |       [断网安装](#断网安装)               |  \n|:-------------------------------|:----------------------:|:----------------------:|:-------------------------:|\n| 生产环境            |   ❌                   |    ✅                  |             ✅            |  \n| 断网安装            |   ❌                   |    ❌                  |             ✅            |\n| 支持Mac            |   ✅                   |    ❌                  |             ❌            |  \n| 支持Linux          |   ✅                   |    ✅                  |             ✅            |  \n| 支持windows WSL    |   ✅                   |    ✅                  |             ✅            |  \n| 支持纯CPU           |   ✅                   |    ❌                  |             ❌            |    \n| 支持混合检索(BM25+embedding)     |   ❌       |    ✅                  |             ✅            |\n\n\n## 纯python环境安装\n\n不想用docker环境安装的，我们提供了[纯Python版本安装教程](https://github.com/netease-youdao/QAnything/blob/qanything-python-v1.3.1/README_zh.md#%E7%BA%AFpython%E7%8E%AF%E5%A2%83%E5%AE%89%E8%A3%85%E6%95%99%E7%A8%8B)，纯python环境的安装仅作为demo体验，不建议生产环境部署。\n\n- 支持纯CPU安装运行(检索部分跑在CPU上，大模型调用在线API)\n- 支持Mac安装运行\n\n\n## docker环境安装\n### 必要条件\n#### **For Linux**\n|**System**| **Required item** | **Minimum Requirement** | **Note**                                                           |\n|---------------------------|-------------------|-------------------------|--------------------------------------------------------------------|\n|Linux | NVIDIA GPU Memory | >= 4GB (use OpenAI API)  | 最低: GTX 1050Ti（use OpenAI API） <br> 推荐: RTX 3090                   |\n|      | NVIDIA Driver Version | >= 525.105.17           |                                                                    |\n|      |  Docker version    | >= 20.10.5              | [Docker install](https://docs.docker.com/engine/install/)          |\n|      | docker compose  version | >= 2.23.3               | [docker compose install](https://docs.docker.com/compose/install/) |\n|      | git-lfs   |                         | [git-lfs install](https://git-lfs.com/)                            |\n\n#### **For Windows with WSL Ubuntu子系统**\n| **System**                 | **Required item**        | **Minimum Requirement**   | **Note**                                                                                                                  |\n|----------------------------|--------------------------|---------------------------|---------------------------------------------------------------------------------------------------------------------------|\n| Windows with WSL Ubuntu子系统 | NVIDIA GPU Memory | >= 4GB (use OpenAI API)                | 最低: GTX 1050Ti（use OpenAI API） <br> 推荐: RTX 3090                                                                          |                                                                |\n|                            | GEFORCE EXPERIENCE    | >= 546.33 | [GEFORCE EXPERIENCE download](https://us.download.nvidia.com/GFE/GFEClient/3.27.0.120/GeForce_Experience_v3.27.0.120.exe) |                                                                                               |\n|                            |  Docker Desktop           | >=  4.26.1（131620）     | [Docker Desktop for Windows](https://docs.docker.com/desktop/install/windows-install/)                                    |\n|                            | git-lfs   |                  | [git-lfs install](https://git-lfs.com/)                                                                                   |\n\n\n\n\n\n### step1: 下载本项目\n```shell\ngit clone https://github.com/netease-youdao/QAnything.git\n```\n### step2: 进入项目根目录执行启动脚本\n* [📖 QAnything_Startup_Usage](docs/QAnything_Startup_Usage_README.md)\n* 执行 ```bash ./run.sh -h``` 获取详细的LLM服务配置方法 \n  \n```shell\ncd QAnything\nbash run.sh  # 默认在0号GPU上启动\n```\n\n<details>\n<summary>（注意）如果自动下载失败，您可以从以下三个地址之一手动下载模型。</summary>\n\nmodelscope: https://modelscope.cn/models/netease-youdao/QAnything\n\nwisemodel: https://wisemodel.cn/models/Netease_Youdao/qanything\n\nhuggingfase: https://huggingface.co/netease-youdao/QAnything\n\n</details>\n\n<details>\n<summary>（可选）指定单GPU启动</summary>\n\n```shell\ncd QAnything\nbash ./run.sh -c local -i 0 -b default # 指定0号GPU启动 GPU编号从0开始 windows机器一般只有一张卡，所以只能指定0号GPU\n```\n</details>\n\n<details>\n<summary>（可选）指定单GPU启动 - 推荐 Windows10/Windows11 WSL2 用户使用此方式运行 QAnything</summary>\n\n```shell\n# 注意: Windows系统请先进入**WSL2**环境\n# Step 1. 下载开源 LLM 模型 (e.g., Qwen-7B-QAnything) 并保存在路径 \"/path/to/QAnything/assets/custom_models\"\n# (可选) 从 ModelScope 下载 Qwen-7B-QAnything: https://www.modelscope.cn/models/netease-youdao/Qwen-7B-QAnything\n# (可选) 从 Huggingface 下载 Qwen-7B-QAnything: https://huggingface.co/netease-youdao/Qwen-7B-QAnything\ncd QAnything/assets/custom_models\ngit clone https://huggingface.co/netease-youdao/Qwen-7B-QAnything\n\n# Step 2. 执行启动命令，其中\"-b hf\"表示指定使用 Huggingface transformers 后端运行 LLM.\ncd ../../\nbash ./run.sh -c local -i 0 -b hf -m Qwen-7B-QAnything -t qwen-7b-qanything\n```\n</details>\n\n<details>\n<summary>（可选）指定单GPU启动 - 推荐 GPU Compute Capability >= 8.6 && VRAM >= 24GB 使用此方式运行 QAnything</summary>\n\n```shell\n# 查看 GPU 算力 GPU Compute Capability: https://developer.nvidia.com/cuda-gpus\n# Step 1. 下载开源 LLM 模型 (e.g., Qwen-7B-QAnything) 并保存在路径 \"/path/to/QAnything/assets/custom_models\"\n# (可选) 从 ModelScope 下载 Qwen-7B-QAnything: https://www.modelscope.cn/models/netease-youdao/Qwen-7B-QAnything\n# (可选) 从 Huggingface 下载 Qwen-7B-QAnything: https://huggingface.co/netease-youdao/Qwen-7B-QAnything\ncd QAnything/assets/custom_models\ngit clone https://huggingface.co/netease-youdao/Qwen-7B-QAnything\n\n# Step 2. 执行启动命令，其中\"-b vllm\"表示指定使用 vllm 后端运行 LLM.\ncd ../../\nbash ./run.sh -c local -i 0 -b vllm -m Qwen-7B-QAnything -t qwen-7b-qanything -p 1 -r 0.85\n```\n</details>\n\n<details>\n<summary>（可选）指定多GPU启动</summary>\n\n```shell\ncd QAnything\nbash ./run.sh -c local -i 0,1 -b default  # 指定0,1号GPU启动，请确认有多张GPU可用，最多支持两张卡启动\n```\n</details>\n\n\n\n\n### step3: 开始体验\n\n#### 前端页面\n运行成功后，即可在浏览器输入以下地址进行体验。\n\n- 前端地址: http://`your_host`:5052/qanything/\n\n#### API\n如果想要访问API接口，请参考下面的地址:\n- API address: http://`your_host`:8777/api/\n- For detailed API documentation, please refer to [QAnything API 文档](docs/API.md)\n\n#### DEBUG\n如果想要查看相关日志，请查看`QAnything/logs/debug_logs`目录下的日志文件。\n- **debug.log**\n  - 用户请求处理日志\n- **sanic_api.log**\n  - 后端服务运行日志\n- **llm_embed_rerank_tritonserver.log**（单卡部署）\n  - LLM embedding和rerank tritonserver服务启动日志\n- **llm_tritonserver.log**（多卡部署）\n  - LLM tritonserver服务启动日志\n- **embed_rerank_tritonserver.log**（多卡部署或使用openai接口）\n  - embedding和rerank tritonserver服务启动日志\n- rerank_server.log\n  - rerank服务运行日志\n- ocr_server.log\n  - OCR服务运行日志\n- npm_server.log\n  - 前端服务运行日志\n- llm_server_entrypoint.log\n  - LLM中转服务运行日志\n- fastchat_logs/*.log\n  - FastChat服务运行日志\n\n### 关闭服务\n```shell\nbash close.sh\n```\n\n## 断网安装\n### windows断网安装\n如果您想要断网安装QAnything，您可以使用以下命令启动服务。\n```shell \n# 先在联网机器上下载docker镜像\ndocker pull quay.io/coreos/etcd:v3.5.5\ndocker pull minio/minio:RELEASE.2023-03-20T20-16-18Z\ndocker pull milvusdb/milvus:v2.3.4\ndocker pull mysql:latest\ndocker pull freeren/qanything-win:v1.2.x  # 从 [https://github.com/netease-youdao/QAnything/blob/master/docker-compose-windows.yaml#L103] 中获取最新镜像版本号。\n\n# 打包镜像\ndocker save quay.io/coreos/etcd:v3.5.5 minio/minio:RELEASE.2023-03-20T20-16-18Z milvusdb/milvus:v2.3.4 mysql:latest freeren/qanything-win:v1.2.1 -o qanything_offline.tar\n\n# 下载QAnything代码\nwget https://github.com/netease-youdao/QAnything/archive/refs/heads/master.zip\n\n# 把镜像qanything_offline.tar和代码QAnything-master.zip拷贝到断网机器上\ncp QAnything-master.zip qanything_offline.tar /path/to/your/offline/machine\n\n# 在断网机器上加载镜像\ndocker load -i qanything_offline.tar\n\n# 解压代码，运行\nunzip QAnything-master.zip\ncd QAnything-master\nbash run.sh\n```\n\n### Linux断网安装\n如果您想要断网安装QAnything，您可以使用以下命令启动服务。\n```shell \n# 先在联网机器上下载docker镜像\ndocker pull quay.io/coreos/etcd:v3.5.5\ndocker pull minio/minio:RELEASE.2023-03-20T20-16-18Z\ndocker pull milvusdb/milvus:v2.3.4\ndocker pull mysql:latest\ndocker pull freeren/qanything:v1.2.x  # 从 [https://github.com/netease-youdao/qanything/blob/master/docker-compose-linux.yaml#L104] 中获取最新镜像版本号。\n\n# 打包镜像\ndocker save quay.io/coreos/etcd:v3.5.5 minio/minio:RELEASE.2023-03-20T20-16-18Z milvusdb/milvus:v2.3.4 mysql:latest freeren/qanything:v1.2.1 -o qanything_offline.tar\n\n# 下载QAnything代码\nwget https://github.com/netease-youdao/QAnything/archive/refs/heads/master.zip\n\n# 把镜像qanything_offline.tar和代码QAnything-master.zip拷贝到断网机器上\ncp QAnything-master.zip qanything_offline.tar /path/to/your/offline/machine\n\n# 在断网机器上加载镜像\ndocker load -i qanything_offline.tar\n\n# 解压代码，运行\nunzip QAnything-master.zip\ncd QAnything-master\nbash run.sh\n```\n\n## 常见问题\n[常见问题](FAQ_zh.md)\n\n\n## 使用\n### 跨语种：多篇英文论文问答\n[![](docs/videos/multi_paper_qa.mp4)](https://github.com/netease-youdao/QAnything/assets/141105427/8915277f-c136-42b8-9332-78f64bf5df22)\n### 信息抽取\n[![](docs/videos/information_extraction.mp4)](https://github.com/netease-youdao/QAnything/assets/141105427/b9e3be94-183b-4143-ac49-12fa005a8a9a)\n### 文件大杂烩\n[![](docs/videos/various_files_qa.mp4)](https://github.com/netease-youdao/QAnything/assets/141105427/7ede63c1-4c7f-4557-bd2c-7c51a44c8e0b)\n### 网页问答\n[![](docs/videos/web_qa.mp4)](https://github.com/netease-youdao/QAnything/assets/141105427/d30942f7-6dbd-4013-a4b6-82f7c2a5fbee)\n\n### 接入API\n如果需要接入API，请参阅[QAnything API 文档](docs/API.md)\n\n## 贡献代码\n我们感谢您对贡献到我们项目的兴趣。无论您是修复错误、改进现有功能还是添加全新内容，我们都欢迎您的贡献！\n\n### 感谢以下所有贡献者\n<a href=\"https://github.com/netease-youdao/QAnything/graphs/contributors\">\n  <img src=\"https://contrib.rocks/image?repo=netease-youdao/QAnything\" />\n</a>\n\n# 🛣️ 路线图 & 反馈\n🔎 想了解QAnything的未来规划和进展，请看这里： [QAnything Roadmap](https://qanything.canny.io/)\n\n🤬 想要给QAnything提交反馈，请看这里(可以给每个功能需求投票哦): [QAnything Feedbak](https://qanything.canny.io/feature-requests)\n\n# 交流 & 支持\n\n## Discord <a href=\"https://discord.gg/5uNpPsEJz8\"><img src=\"https://img.shields.io/discord/1197874288963895436?style=social&logo=discord\"></a>\n欢迎加入QAnything [Discord](https://discord.gg/5uNpPsEJz8) 社区！\n\n\n\n## 微信\n欢迎关注微信公众号，获取最新QAnything信息\n\n<img src=\"docs/images/qrcode_for_qanything.jpg\" width=\"30%\" height=\"auto\">\n\n欢迎扫码进入QAnything交流群\n\n<img src=\"docs/images/Wechat.jpg\" width=\"30%\" height=\"auto\">\n\n## 邮箱\n如果你需要私信我们团队，请通过下面的邮箱联系我们：\n\nqanything@rd.netease.com\n\n## GitHub issues & discussions\n有任何公开的问题，欢迎提交issues，或者在discussions区讨论\n- [Github issues](https://github.com/netease-youdao/QAnything/issues)\n- [Github discussions](https://github.com/netease-youdao/QAnything/discussions)\n<a href=\"https://github.com/netease-youdao/QAnything/discussions\">\n  <!-- Please provide path to your logo here -->\n  <img src=\"https://github.com/netease-youdao/QAnything/assets/29041332/ad027ec5-0bbc-4ea0-92eb-81b30c5359a1\" alt=\"Logo\" width=\"600\">\n</a>\n\n# Star History\n\n[![Star History Chart](https://api.star-history.com/svg?repos=netease-youdao/QAnything,netease-youdao/BCEmbedding&type=Date)](https://star-history.com/#netease-youdao/QAnything&netease-youdao/BCEmbedding&Date)\n\n# 协议\n\n`QAnything` 依照 [Apache 2.0 协议](./LICENSE)开源。\n\n# Acknowledgements\n- [BCEmbedding](https://github.com/netease-youdao/BCEmbedding)\n- [Qwen](https://github.com/QwenLM/Qwen)\n- [Triton Inference Server](https://github.com/triton-inference-server/server)\n- [vllm](https://github.com/vllm-project/vllm)\n- [FastChat](https://github.com/lm-sys/FastChat)\n- [FasterTransformer](https://github.com/NVIDIA/FasterTransformer)\n- [Langchain](https://github.com/langchain-ai/langchain)\n- [Langchain-Chatchat](https://github.com/chatchat-space/Langchain-Chatchat)\n- [Milvus](https://github.com/milvus-io/milvus)\n- [PaddleOCR](https://github.com/PaddlePaddle/PaddleOCR) \n- [Sanic](https://github.com/sanic-org/sanic)\n',
        34805598);
INSERT INTO `repository`
VALUES (10000081, 'blcok007_admin/Qbot', 'https://gitee.com/blcok007_admin/Qbot.git',
        '<div>\n  <div align=\"right\">\n    👆 右上角点击 <img class=\"ai-header-badge-img\" src=\"https://img.shields.io/github/stars/UFund-Me/Qbot.svg?style=social&label=Star\"> 告诉我，你希望这个项目继续加速开发迭代 ❤️ & ☕️\n  </div>\n  <h1> 🤖 Qbot </h1>\n</div>\n\n<p align=\"left\">\n    <img alt=\"ViewCount\" valign=\"bottom\" src=\"https://views.whatilearened.today/views/github/UFund-Me/Qbot.svg\">\n    <a href=\'https://github.com/MShawon/github-clone-count-badge\'><img alt=\'GitHub Clones\' valign=\"bottom\" src=\'https://img.shields.io/badge/dynamic/json?color=success&label=Clone&query=count&url=https://gist.githubusercontent.com/MShawon/cf89f3274d06170b8a4973039aa6220a/raw/clone.json&logo=github\'></a>\n    <img alt=\"releases\" valign=\"bottom\" src=\"https://img.shields.io/github/downloads/UFund-Me/Qbot/total\"> <code>since Sep 26</code>\n</p>\n\n[![CodeQL](https://github.com/UFund-Me/Qbot/actions/workflows/codeql-analysis.yml/badge.svg)](https://github.com/UFund-Me/Qbot/actions/workflows/codeql-analysis.yml)\n[![AutoTrade](https://github.com/UFund-Me/Qbot/actions/workflows/auto-trade.yml/badge.svg)](https://github.com/UFund-Me/Qbot/actions/workflows/auto-trade.yml)\n[![Pylint](https://github.com/UFund-Me/Qbot/actions/workflows/pylint.yml/badge.svg)](https://github.com/UFund-Me/Qbot/actions/workflows/pylint.yml)\n[![Coverage](https://github.com/UFund-Me/Qbot/actions/workflows/coverage.yml/badge.svg)](https://github.com/UFund-Me/Qbot/actions/workflows/coverage.yml)\n<a href=\"https://github.com/UFund-Me/Qbot\"><img src=\"https://img.shields.io/badge/Python-%203.8|%203.9-000000.svg?logo=Python&color=blue\" alt=\"Python version\"></a>\n<a href=\"https://ufund-me.github.io/Qbot/#/\"><img src=\"https://readthedocs.org/projects/pyod/badge/?version=latest\" alt=\"Documentation status\"></a>\n\n<div align=\"center\">\n  <a href=\"https://github.com/UFund-Me/Qbot\" target=\"_blank\" rel=\"noopener\">\n    <picture>\n      <source media=\"(prefers-color-scheme: dark)\" alt=\"Qbot\" srcset=\"https://user-images.githubusercontent.com/29084184/204598632-23c473db-92ee-4e9b-9b57-d6d95c861fdf.png\" />\n      <img alt=\"Qbot\" width=\"224\" src=\"https://user-images.githubusercontent.com/29084184/204598632-23c473db-92ee-4e9b-9b57-d6d95c861fdf.png\" />\n    </picture>\n  </a>\n  <div>&nbsp;</div>\n  <div align=\"center\">\n    <b><font size=\"5\">Qbot website</font></b>\n    <sup>\n      <a href=\"https://ufund-me.github.io/Qbot/#/\">\n        <i><font size=\"4\">HOT</font></i>\n      </a>\n    </sup>\n    &nbsp;&nbsp;&nbsp;&nbsp;\n    <b><font size=\"5\">Qbot platform</font></b>\n    <sup>\n      <a href=\"https://ufund-me.github.io/Qbot/quantstats/docs/tearsheet.html\">\n        <i><font size=\"4\">TRY IT OUT</font></i>\n      </a>\n    </sup>\n  </div>\n  <div>&nbsp;</div>\n</div>\n\n<div align=\"center\">\n  <p>AI智能量化投研平台</p>\n</div>\n\n>  <b>Qbot</b> is an AI-oriented automated quantitative investment platform, which aims to realize the potential, empower AI technologies in quantitative investment. Qbot supports diverse machine learning modeling paradigms. including supervised learning, market dynamics modeling, and RL.\n\n<p id=\"demo\">\n  <!-- <img width=\"\" alt=\"demo\" src=\"https://user-images.githubusercontent.com/29084184/221901048-bb1615fe-674f-40e8-b1e7-ba5db30a82a6.png\"> -->\n  <img width=\"\" alt=\"demo\" src=\"https://user-images.githubusercontent.com/29084184/223608757-5808e23c-86e4-4b1b-8b03-e04c8f368f5c.gif\">\n</p>\n\n```\n🤖 Qbot = 智能交易策略 + 回测系统 + 自动化量化交易 (+ 可视化分析工具)\n            |           |            |            |\n            |           |            |             \\_ quantstats (dashboard\\online operation)\n            |           |             \\______________ Qbot - vnpy, pytrader, pyfunds\n            |           \\____________________________ BackTest - backtrader, easyquant\n            \\________________________________________ quant.ai - qlib, deep learning strategies\n```\n\n<br>\n\n<div align=\"center\">\n  \n  🎺 <b>号外</b>：Qbot微信小程序开发招募 [UFund-miniprogram](https://github.com/UFund-Me/UFund-miniprogram)\n\n  <b>不建议 fork 项目，本项目会持续更新，只 fork 看不到更新，建议 Star ⭐️ ~</b>\n\n  <i>喜欢这个项目吗？请考虑[ ❤️赞助](#sponsors--support) 本项目，以帮助改进！</i>\n\n</div>\n\n## Quick Start\n\nQbot是一个免费的量化投研平台，提供从数据获取、交易策略开发、策略回测、模拟交易到最终实盘交易的全闭环流程。在实盘接入前，有股票、基金评测和策略回测，在模拟环境下做交易验证，近乎实盘的时延、滑点仿真。故，本平台提供GUI前端/客户端（部分功能也支持网页），后端做数据处理、交易调度，实现事件驱动的交易流程。对于策略研究部分，尤其强调机器学习、强化学习的AI策略，结合多因子模型提高收益比。\n\n但本项目可能需要一点点python基础知识，有一点点交易经验，会更容易体会作者的初衷，解决当下产品空缺和广大散户朋友的交易痛点，现在直接免费开源出来！\n\n```bash\ncd ~ # $HOME as workspace\ngit clone https://github.com/UFund-Me/Qbot --depth 1\n\ncd Qbot\npip install -r requirements.txt\n\nexport PYTHONPATH=${PYTHONPATH}:$(pwd):$(pwd)/backend/multi-fact/mfm_learner\npython main.py  #if run on Mac, please use \'pythonw main.py\'\n\n```\n\n详细文档 https://github.com/UFund-Me/Qbot/blob/main/quick_start.md\n\n> [!NOTE]\n> - wxPython、Ta-Lib 需要手动安装，pip wheel 在 dev/ 路径下。https://github.com/UFund-Me/Qbot/issues/76\n> - <details><summary>Mac系统在安装之前需要手动安装tables库的依赖hdf5，以及pythonw https://github.com/UFund-Me/Qbot/issues/11 </summary>\n> <code>\n>   brew install hdf5\n>   brew install c-blosc\n>   export HDF5_DIR=/opt/homebrew/opt/hdf5 \n>   export BLOSC_DIR=/opt/homebrew/opt/c-blosc\n> </code>\n> </details>\n\n[![Open in Gitpod](https://gitpod.io/button/open-in-gitpod.svg)](https://gitpod.io/#https://github.com/UFund-Me/Qbot)\n\n<!-- ![Gitpod-Ready](https://img.shields.io/badge/Gitpod-Ready--to--Code-blue?logo=gitpod) -->\n\n## Highlights\n\n<table class=\"table table-striped table-bordered table-vcenter\">\n    <tbody class=ai-notebooks-table-content>\n    <tr>\n        <td colspan=\"3\" rowspan=\"1\" class=\"ai-notebooks-table-points ai-orange-link\">\n            <div class=\"features-2 mdl-grid\">\n                <h2 style=\"text-align:center\">1. 模块化分层设计：数据层、策略层、交易引擎抽象设计</h2>\n                <p>- 数据、策略中间表达，方便多种数据接口、交易接口接入，用户自定义策略和因子挖掘<br> - 支持多种交易对象：股票、基金、期货、虚拟货币</p>\n            </div>\n        </td>\n    </tr>\n    <tr>\n        <td>\n            <div class=\"mdl-cell mdl-cell--4-col\">\n                <img class=\"illustration_img\" width=\"330\" src=\"./docs/statics/imgs/backtest_sample.png\"></img>\n            </div>\n        </td>\n        <td>\n            <div class=\"mdl-cell mdl-cell--4-col\">\n                <img class=\"illustration_img\" width=\"330\" src=\"./docs/statics/imgs/factor-express.png\"/>\n            </div>\n        </td>\n        <td>\n            <div class=\"mdl-cell mdl-cell--4-col\">\n                <img class=\"illustration_img\" width=\"330\" src=\"./docs/statics/imgs/fund_strategy.png\"/>\n            </div>\n        </td>\n    </tr>\n    <tr>\n        <td>\n            <div class=\"mdl-cell mdl-cell--4-col\">\n                <img class=\"illustration_img\" width=\"330\" src=\"./docs/statics/imgs/indicator_analyse.png\"/>\n            </div>\n        </td>\n        <td>\n            <div class=\"mdl-cell mdl-cell--4-col\">\n                <img class=\"illustration_img\" width=\"330\" src=\"./docs/statics/imgs/juejin_trade.png\"/>\n            </div>\n        </td>\n        <td>\n            <div class=\"mdl-cell mdl-cell--4-col\">\n                <img class=\"illustration_img\" width=\"330\" src=\"./docs/statics/imgs/relationship_analyse.png\"/>\n            </div>\n        </td>\n    </tr>\n    </tbody>\n</table>\n\n<table class=\"table table-striped table-bordered table-vcenter\">\n    <tbody class=ai-notebooks-table-content>\n    <tr>\n        <td colspan=\"3\" rowspan=\"1\" class=\"ai-notebooks-table-points ai-orange-link\">\n            <div class=\"features-2 mdl-grid\">\n                <h2 style=\"text-align:center\">2. 人工智能交易策略、自动化因子挖掘</h2>\n                <p>机器学习、强化学习、深度学习策略开发，因子挖掘自动化workflow</p>\n            </div>\n        </td>\n    </tr>\n    <tr>\n        <td>\n            <div class=\"mdl-cell mdl-cell--4-col\">\n                <img class=\"illustration_img\" width=\"330\" src=\"./docs/statics/imgs/model_zoo.png\"></img>\n            </div>\n        </td>\n        <td>\n            <div class=\"mdl-cell mdl-cell--4-col\">\n                <img class=\"illustration_img\" width=\"330\" src=\"./docs/statics/imgs/multi-factors.png\"/>\n            </div>\n        </td>\n        <td>\n            <div class=\"mdl-cell mdl-cell--4-col\">\n                <img class=\"illustration_img\" width=\"330\" src=\"./docs/statics/imgs/indicator_list.png\"/>\n            </div>\n        </td>\n    </tr>\n    </tbody>\n</table>\n\n<table class=\"table table-striped table-bordered table-vcenter\">\n    <tbody class=ai-notebooks-table-content>\n    <tr>\n        <td colspan=\"3\" rowspan=\"1\" class=\"ai-notebooks-table-points ai-orange-link\">\n            <div class=\"features-2 mdl-grid\">\n                <h2 style=\"text-align:center\">3. 多种交易方式：在线回测 + 模拟交易 + 实盘自动化交易</h2>\n                <p>以策略研究为目标，提供多种交易方式验证策略和提高收益。</p>\n            </div>\n        </td>\n    </tr>\n    <tr>\n        <td>\n            <div class=\"mdl-cell mdl-cell--4-col\">\n                <img class=\"illustration_img\" width=\"330\" src=\"https://github.com/UFund-Me/Qbot/assets/29084184/222de589-a61f-4c45-bc5f-49de3fc2a72e\"></img>\n            </div>\n        </td>\n        <td>\n            <div class=\"mdl-cell mdl-cell--4-col\">\n                <img class=\"illustration_img\" width=\"330\" src=\"https://user-images.githubusercontent.com/29084184/221901048-bb1615fe-674f-40e8-b1e7-ba5db30a82a6.png\"/>\n            </div>\n        </td>\n        <td>\n            <div class=\"mdl-cell mdl-cell--4-col\">\n                <img class=\"illustration_img\" width=\"330\" src=\"https://github.com/UFund-Me/Qbot/assets/29084184/e96206ff-586a-4c6a-8f7a-cd578c8bdc43\"/>\n            </div>\n        </td>\n    </tr>\n    </tbody>\n</table>\n\n<table class=\"table table-striped table-bordered table-vcenter\">\n    <tbody class=ai-notebooks-table-content>\n    <tr>\n        <td colspan=\"3\" rowspan=\"1\" class=\"ai-notebooks-table-points ai-orange-link\">\n            <div class=\"features-2 mdl-grid\">\n                <h2 style=\"text-align:center\">4. 多种提示方式：邮件 + 飞书 + 弹窗 + 微信</h2>\n                <p>这是qbot的消息提示模块，多种方式提示交易信息：交易买卖信息、每日交易收益结果、股票每日推荐等。</p>\n            </div>\n        </td>\n    </tr>\n    <tr>\n        <td>\n            <div class=\"mdl-cell mdl-cell--4-col\">\n                <img class=\"illustration_img\" width=\"330\" src=\"https://github.com/UFund-Me/Qbot/assets/29084184/aafff916-1945-4ae7-b836-60254ecacf76\"></img>\n            </div>\n        </td>\n        <td>\n            <div class=\"mdl-cell mdl-cell--4-col\">\n                <img class=\"illustration_img\" width=\"220\" src=\"https://github.com/UFund-Me/Qbot/assets/29084184/a5cfadb5-8233-4307-ab79-6e0c0aca536d\"/>\n            </div>\n        </td>\n        <td>\n            <div class=\"mdl-cell mdl-cell--4-col\">\n                <img class=\"illustration_img\" width=\"330\" height=\"150%\" src=\"https://github.com/UFund-Me/Qbot/assets/29084184/beb5877b-e45e-45a8-afdb-1926ea2ea8a1\"/>\n            </div>\n        </td>\n    </tr>\n    </tbody>\n</table>\n\n## Strategy pool\n\n通过Qbot 可以积木式完成策略编写、多因子挖掘，实现数据开发、因子开发、组合优化、交易执行的[量化交易全流程](docs/01-新手指引/量化策略的分类和原理.md#1量化选股策略)。\n\n<b>如果说策略是量化的核心 ，那么因子就是策略的核心。</b>通过Qbot量化投研平台研究员可实现自动化因子挖掘，提取出具备预测能力的单因子，利用历史数据进行回测，如果回测结果显示该因子的预测能力达标，就提交到因子库。然后，对因子库里的因子进行有机组合，以形成预测模型，预测模型是整个量化策略的目标。\n\n以下即为，<u>数据指标单因子或组合因子</u>和<u>通过深度学习、机器学习、强化学习挖掘到的交易因子</u>，然后通过组合优化算法实现趋势交易、风险策略、alpha策略、动量轮动等等交易策略。\n\n策略库源代码路径：[qbot/strategy](qbot/strategy)\n\n\n<div align=\"center\">\n  <b>经典策略</b>\n</div>\n<table align=\"center\">\n  <tbody>\n    <tr align=\"center\" valign=\"bottom\">\n      <td>\n        <b>交易对象</b>\n      </td>\n      <td>\n        <b>选股</b>\n      </td>\n      <td>\n        <b>择时</b>\n      </td>\n      <td>\n        <b>风险控制 (组合、仓位管理)</b>\n      </td>\n    </tr>\n    <tr valign=\"top\">\n      <td>\n        <b>股票/期货/虚拟货币</b>\n      </td>\n      <td>\n        <ul>\n          <li><a href=\"docs/02-经典策略/01-股票/布林线均值回归.md\">布林线均值回归 (\'2022)</a></li>\n          <li><a href=\"docs/tutorials_code/05.kdj_macd_in_A_market\">移动均线+KDJ</a></li>\n          <li><a href=\"qbot/strategy/bigger_than_ema_bt.py\">简单移动均线</a></li>\n          <li><a href=\"qbot/strategy/arbr_strategy.py\">情绪指标ARBR</a></li>\n          <li><a href=\"qbot/strategy/aroon_strategy.py\">阿隆指标(趋势交易)</a></li>\n          <li><a href=\"qbot/strategy/lgb_strategy.py\">LightGBM 预测</a></li>\n          <li><a href=\"qbot/strategy/svm_strategy.py\">SVM 预测</a></li>\n          <li><a href=\"qbot/strategy/lstm_strategy_bt.py\">LSTM时序预测</a></li>\n          <li><a href=\"qbot/strategy/rl_strategy_bt.py\">强化学习预测</a></li>\n          <li><a href=\"qbot/strategy/q-learning.py\">Q-Leaning预测</a></li>\n          <li><a href=\"docs/tutorials_code/11_RandomForest\">随机森林预测</a></li>\n          <li><a href=\"qbot/strategy/rsi_departure_strategy.py\">RSI背离策略</a></li>\n          <li><a href=\"qbot/strategy/ssa_strategy_bt.py\">麻雀优化算法SSA</a></li>\n          <li><a href=\"qbot/strategy/stoch_rsi_strategy.py\">随机相对强弱指数 StochRSI</a></li>\n          <li><a href=\"docs/02-经典策略/01-股票/小市值.md\">小市值 (\'2021)</a></li>\n          <li><a href=\"qbot/strategy/undervalued_stock_picking_strategy.py\">市场低估值策略</a></li>\n          <li><a href=\"docs/02-经典策略/01-股票/量化策略-RSRS择时.md\">RSRS择时</a></li>\n          <li><a href=\"docs/02-经典策略/01-股票/量化三-配对交易.md\">配对交易</a></li>\n        </ul>\n      </td>\n      <td>\n        <li><b>传统指标（对应下方Qbot支持的指标 <a href=\"#交易指标因子\">这里</a>）</b></li>\n        <ul>\n          <li><a href=\"docs/02-经典策略/01-股票/布林线均值回归.md\">布林线均值回归 (\'2022)</a></li>\n          <li><a href=\"docs/tutorials_code/05.kdj_macd_in_A_market\">移动均线+KDJ</a></li>\n          <li><a href=\"qbot/strategy/bigger_than_ema_bt.py\">简单移动均线</a></li>\n          <li><a href=\"qbot/strategy/klines_bt.py\">双均线策略 (\'2022)</a></li>\n          <li><a href=\"qbot/strategy/arbr_strategy.py\">情绪指标ARBR</a></li>\n          <li><a href=\"qbot/strategy/aroon_strategy.py\">阿隆指标(趋势交易)</a></li>\n          <li><a href=\"qbot/strategy/lgb_strategy.py\">LightGBM 预测</a></li>\n          <li><a href=\"qbot/strategy/svm_strategy.py\">SVM 预测</a></li>\n          <li><a href=\"qbot/strategy/lstm_strategy_bt.py\">LSTM时序预测</a></li>\n          <li><a href=\"qbot/strategy/rl_strategy_bt.py\">强化学习预测</a></li>\n          <li><a href=\"qbot/strategy/q-learning.py\">Q-Leaning预测</a></li>\n          <li><a href=\"docs/tutorials_code/11_RandomForest\">随机森林预测</a></li>\n          <li><a href=\"qbot/strategy/rsi_departure_strategy.py\">RSI背离策略</a></li>\n          <li><a href=\"qbot/strategy/ssa_strategy_bt.py\">麻雀优化算法SSA</a></li>\n          <li><a href=\"qbot/strategy/stoch_rsi_strategy.py\">随机相对强弱指数 StochRSI</a></li>\n        </ul>\n        <li><b>因子组合</b></li>\n        <ul>\n          <li><a href=\"qbot/strategy/rsi_cci_strategy.py\">RSI和CCI组合</a></li>\n          <li><a href=\"qbot/strategy/adx_strategy.py\">MACD和ADX指标</a></li>\n          <li><a href=\"docs/tutorials_code/05.kdj_macd_in_A_market\">MACD和KDJ指标</a></li>\n          <li><a href=\"qbot/strategy/multi_strategy_bt.py\">多因子交易</a></li>\n          <li><a href=\"docs/tutorials_code/13.alphalens_factor_backtest\">alphalens多因子交易</a></li>\n          <li><a href=\"docs/tutorials_code/08.harami_in_A_market\">多策略整合</a></li>\n          <li><a href=\"docs/notebook/Kurtosis Portfolio.ipynb\">组合策略</a></li>\n          <li><a href=\"docs/02-经典策略/01-股票/指数增强.md\">指数增强 (\'2022)</a></li>\n        </ul>\n        <li><b>经典策略</b></li>\n        <ul>\n          <li><a href=\"docs/02-经典策略/01-股票/多因子选股.md\">多因子选股 (\'2023)</a></li>\n          <li><a href=\"docs/02-经典策略/01-股票/指数增强.md\">指数增强 (\'2022)</a></li>\n          <li><a href=\"docs/02-经典策略/01-股票/Alpha对冲.md\">Alpha对冲 (\'2022)</a></li>\n          <li><a href=\"docs/02-经典策略/03-期货/网络交易.md\">网格交易</a></li>\n          <li><a href=\"docs/02-经典策略/03-期货/双均线策略.md\">双均线策略 (\'2022)</a></li>\n          <li><a href=\"docs/03-智能策略/拐点交易.md\">拐点交易 (\'2022)</a></li>\n          <li><a 